import{_ as o,o as r,c as d,a6 as a}from"./chunks/framework.QBF2cGGQ.js";const g=JSON.parse('{"title":"14 · 岗位画像与能力矩阵","description":"","frontmatter":{},"headers":[],"relativePath":"guide/14-jobs.md","filePath":"guide/14-jobs.md","lastUpdated":1793327470000}'),e={name:"guide/14-jobs.md"};function n(l,t,s,i,p,u){return r(),d("div",null,[...t[0]||(t[0]=[a('<h1 id="_14-·-岗位画像与能力矩阵" tabindex="-1">14 · 岗位画像与能力矩阵 <a class="header-anchor" href="#_14-·-岗位画像与能力矩阵" aria-label="Permalink to &quot;14 · 岗位画像与能力矩阵&quot;">​</a></h1><blockquote><p>这一章回答一个问题：<strong>招聘方到底在找什么样的人，以及你现在的差距具体在哪。</strong></p></blockquote><h2 id="一、先把岗位分清楚" tabindex="-1">一、先把岗位分清楚 <a class="header-anchor" href="#一、先把岗位分清楚" aria-label="Permalink to &quot;一、先把岗位分清楚&quot;">​</a></h2><p>&quot;AI 应用工程师&quot;不是一个标准化职位，市面上至少有三类，要求差别很大。投错方向，你会觉得&quot;我明明会为什么不要我&quot;。</p><h3 id="类型-a-ai-应用工程师-llm-应用开发" tabindex="-1">类型 A：AI 应用工程师 / LLM 应用开发 <a class="header-anchor" href="#类型-a-ai-应用工程师-llm-应用开发" aria-label="Permalink to &quot;类型 A：AI 应用工程师 / LLM 应用开发&quot;">​</a></h3><p><strong>做什么</strong>：把一个业务场景做成可用的 AI 产品。从需求、数据、检索、编排、前端到上线，全链路都碰。</p><p><strong>典型要求</strong>：</p><ul><li>熟练 Python 或 TypeScript，能独立写服务</li><li>有 RAG 落地经验（注意是&quot;落地&quot;，不是&quot;了解&quot;）</li><li>会用主流模型 API，理解 prompt 工程</li><li>能设计评测方案</li><li>有完整项目从 0 到 1 的经历</li></ul><p><strong>面试重点</strong>：项目细节、指标、踩过的坑。技术深度其次，**&quot;你真的做过吗&quot;**是第一位。</p><p><strong>匹配度</strong>：★★★★★ 前端转岗最现实的入口。</p><h3 id="类型-b-llm-工程师-算法应用工程师" tabindex="-1">类型 B：LLM 工程师 / 算法应用工程师 <a class="header-anchor" href="#类型-b-llm-工程师-算法应用工程师" aria-label="Permalink to &quot;类型 B：LLM 工程师 / 算法应用工程师&quot;">​</a></h3><p><strong>做什么</strong>：偏模型侧。微调、蒸馏、评测体系、推理优化。</p><p><strong>典型要求</strong>：</p><ul><li>熟悉 Transformer、SFT、LoRA、DPO</li><li>有微调实战（数据构造、超参、效果评估）</li><li>懂推理框架（vLLM / SGLang）</li><li>通常要求硕士或论文</li></ul><p><strong>面试重点</strong>：原理深度、训练细节、指标对比。</p><p><strong>匹配度</strong>：★★☆☆☆ 需要补的太多，不建议作为第一目标。但可以作为第二年方向。</p><h3 id="类型-c-ai-产品工程师-ai-全栈" tabindex="-1">类型 C：AI 产品工程师 / AI 全栈 <a class="header-anchor" href="#类型-c-ai-产品工程师-ai-全栈" aria-label="Permalink to &quot;类型 C：AI 产品工程师 / AI 全栈&quot;">​</a></h3><p><strong>做什么</strong>：小团队里一个人扛整个产品。前端 + 后端 + AI 全包。</p><p><strong>典型要求</strong>：</p><ul><li>前端熟练（React / Vue）</li><li>能写后端 API</li><li>懂 AI 能力边界，能把控产品形态</li><li>通常出现在创业公司或大厂创新业务</li></ul><p><strong>面试重点</strong>：全栈能力、产品判断、上手速度。</p><p><strong>匹配度</strong>：★★★★★ 你的前端背景在这里是加分而不是减分。</p><blockquote><p><strong>建议路径</strong>：先进 A 或 C，做满一年有真实项目后再考虑 B。</p></blockquote><h2 id="二、jd-里那些话翻译过来是什么" tabindex="-1">二、JD 里那些话翻译过来是什么 <a class="header-anchor" href="#二、jd-里那些话翻译过来是什么" aria-label="Permalink to &quot;二、JD 里那些话翻译过来是什么&quot;">​</a></h2><p>招聘描述有一套自己的黑话。看懂这些，你就知道该准备什么。</p><table tabindex="0"><thead><tr><th>JD 原文</th><th>真实含义</th><th>你该怎么准备</th></tr></thead><tbody><tr><td>熟悉 RAG 技术栈</td><td>至少做过一个能上线的知识库</td><td>准备一个带指标的项目，能讲清分块和重排</td></tr><tr><td>有 LLM 应用落地经验</td><td>你踩过坑，不是只跑过 demo</td><td>准备 2~3 个真实故障的排查过程</td></tr><tr><td>熟悉 Prompt Engineering</td><td>会写结构化 prompt，不是会念咒</td><td>能讲 prompt 版本管理和 A/B 评测</td></tr><tr><td>具备工程化能力</td><td>你写的东西别人能维护</td><td>讲清你的架构分层、日志、配置管理</td></tr><tr><td>了解 Agent</td><td>知道它能做什么、不能做什么</td><td>讲清你为什么在某场景<strong>没</strong>用自主 Agent</td></tr><tr><td>有较强的学习能力</td><td>这行变得快，别只会一个框架</td><td>讲你最近三个月学了什么、怎么学的</td></tr><tr><td>熟悉向量数据库</td><td>用过，知道怎么选</td><td>能对比 pgvector 和 Milvus 的取舍</td></tr><tr><td>有 ToB 项目经验</td><td>你处理过权限、私有化、合规</td><td>准备权限隔离和私有部署的细节</td></tr></tbody></table><p><strong>一个关键判断</strong>：JD 里写&quot;了解&quot;的，面试最多问一层；写&quot;熟悉/精通&quot;的，会追问到底层。别把精力平均分配。</p><h2 id="三、能力矩阵-自评用" tabindex="-1">三、能力矩阵（自评用） <a class="header-anchor" href="#三、能力矩阵-自评用" aria-label="Permalink to &quot;三、能力矩阵（自评用）&quot;">​</a></h2><p>十二项能力，四级。<strong>这个分级是我的判断，不是行业标准</strong>，但拿来定位差距够用。</p><table tabindex="0"><thead><tr><th>能力项</th><th>L1 知道</th><th>L2 做过</th><th>L3 做好过</th><th>L4 能教人</th></tr></thead><tbody><tr><td><strong>1. 模型调用与参数</strong></td><td>会调 API</td><td>懂 temperature 影响</td><td>能按场景定参数并解释</td><td>能建立团队规范</td></tr><tr><td><strong>2. Prompt 工程</strong></td><td>会写 prompt</td><td>会结构化 + few-shot</td><td>有版本管理和评测驱动</td><td>能设计 prompt 体系</td></tr><tr><td><strong>3. 上下文管理</strong></td><td>知道窗口限制</td><td>会做历史裁剪</td><td>会动态组装 + 压缩</td><td>能设计上下文架构</td></tr><tr><td><strong>4. 文档解析与清洗</strong></td><td>会用 loader</td><td>处理过 PDF 难点</td><td>建过解析流水线</td><td>能评估解析质量并优化</td></tr><tr><td><strong>5. 检索（含混合+重排）</strong></td><td>会向量检索</td><td>会混合检索</td><td>有 Recall 指标优化经验</td><td>能设计检索架构</td></tr><tr><td><strong>6. 评测体系</strong></td><td>知道要评测</td><td>建过评测集</td><td>有 LLM-judge 校准经验</td><td>能建评测流程并进 CI</td></tr><tr><td><strong>7. Agent 与工具</strong></td><td>会 function calling</td><td>写过 ReAct</td><td>有可靠性设计（终止/幂等/审批）</td><td>能设计多 Agent 架构</td></tr><tr><td><strong>8. 后端工程</strong></td><td>会写接口</td><td>会异步 + 队列</td><td>懂限流熔断降级</td><td>能设计高可用架构</td></tr><tr><td><strong>9. 前端交互</strong></td><td>会写页面</td><td>会流式渲染</td><td>解决过性能与抖动问题</td><td>能定义交互范式</td></tr><tr><td><strong>10. 可观测与成本</strong></td><td>会打日志</td><td>接入了 trace</td><td>有成本优化案例</td><td>能建成本模型</td></tr><tr><td><strong>11. 安全与合规</strong></td><td>知道有风险</td><td>做过输入输出校验</td><td>处理过权限隔离</td><td>能过合规评审</td></tr><tr><td><strong>12. 部署与运维</strong></td><td>会部署</td><td>会容器化</td><td>做过容量规划</td><td>能定 SLA</td></tr></tbody></table><h3 id="怎么用这张表" tabindex="-1">怎么用这张表 <a class="header-anchor" href="#怎么用这张表" aria-label="Permalink to &quot;怎么用这张表&quot;">​</a></h3><p><strong>上岗门槛</strong>：第 1~7 项至少 L2，其中 5（检索）和 6（评测）要到 L3。</p><p><strong>为什么是这两项</strong>：面试官判断&quot;你是不是真做过&quot;，最常用的两个探针就是&quot;你的召回率多少、怎么测的&quot;和&quot;你怎么知道改完变好了&quot;。这两题答不上来，其他说得再好也会被归为&quot;只跑过 demo&quot;。</p><p><strong>你的现状</strong>（按前端背景推断，你可以自己修正）：</p><ul><li>第 9 项大概已经是 L3~L4，这是你的存量</li><li>第 8 项大概 L2，补异步和队列就够</li><li>第 4、5、6 项是 0，这是必须补的</li><li>第 7 项是 0，但补起来快</li></ul><h2 id="四、简历怎么写" tabindex="-1">四、简历怎么写 <a class="header-anchor" href="#四、简历怎么写" aria-label="Permalink to &quot;四、简历怎么写&quot;">​</a></h2><p>技术能力相同的情况下，简历决定你有没有面试机会。三条规则：</p><h3 id="规则一-每个项目必须有数字" tabindex="-1">规则一：每个项目必须有数字 <a class="header-anchor" href="#规则一-每个项目必须有数字" aria-label="Permalink to &quot;规则一：每个项目必须有数字&quot;">​</a></h3><p>对比一下：</p><blockquote><p>❌ 使用 LangChain 和向量数据库搭建了企业知识库问答系统，支持文档上传和智能问答。</p></blockquote><blockquote><p>✅ 独立搭建企业知识库问答系统，处理 1.2 万份 PDF（含 30% 扫描件），自建解析流水线解决双栏与跨页表格问题；混合检索 + bge-reranker 重排，200 条评测集上 Recall@5 从 62% 提升到 89%；通过父子块与上下文压缩把单次成本降低 40%。</p></blockquote><p>第二段没有用任何高级词，但它证明了四件事：你处理过脏数据、你知道怎么量化、你做过优化、你有成本意识。</p><h3 id="规则二-写-我解决了什么-不写-我用了什么" tabindex="-1">规则二：写&quot;我解决了什么&quot;，不写&quot;我用了什么&quot; <a class="header-anchor" href="#规则二-写-我解决了什么-不写-我用了什么" aria-label="Permalink to &quot;规则二：写&quot;我解决了什么&quot;，不写&quot;我用了什么&quot;&quot;">​</a></h3><p>技术栈是门槛，不是亮点。面试官默认你会用工具，他想知道的是<strong>你解决了什么别人解决不了的问题</strong>。</p><h3 id="规则三-准备三个-深挖点" tabindex="-1">规则三：准备三个&quot;深挖点&quot; <a class="header-anchor" href="#规则三-准备三个-深挖点" aria-label="Permalink to &quot;规则三：准备三个&quot;深挖点&quot;&quot;">​</a></h3><p>简历上每个项目，你都要预判面试官会往哪里挖，并且准备好三层深度的回答：</p><ul><li>第一层：做了什么（30 秒）</li><li>第二层：怎么做的，为什么这么选（2 分钟）</li><li>第三层：遇到过什么坑，怎么定位的，如果重做会怎么改（5 分钟）</li></ul><p><strong>第三层是分水岭。</strong> 能讲清&quot;如果重做会怎么改&quot;的人，说明他真的复盘过；讲不出来的人，多半是跟着教程做的。</p><h2 id="五、面试流程与各轮重点" tabindex="-1">五、面试流程与各轮重点 <a class="header-anchor" href="#五、面试流程与各轮重点" aria-label="Permalink to &quot;五、面试流程与各轮重点&quot;">​</a></h2><p>典型流程四到五轮，每轮考察的东西完全不同，准备策略也不同。</p><h3 id="第一轮-技术初筛-30-45-分钟" tabindex="-1">第一轮：技术初筛（30~45 分钟） <a class="header-anchor" href="#第一轮-技术初筛-30-45-分钟" aria-label="Permalink to &quot;第一轮：技术初筛（30~45 分钟）&quot;">​</a></h3><p>通常问基础概念 + 项目概览。</p><p><strong>重点</strong>：能不能把项目讲清楚。这轮淘汰的是&quot;简历写得比实际好&quot;的人。</p><p><strong>准备</strong>：把项目讲成 3 分钟版本，包含背景、你的角色、技术选型理由、结果数字。</p><h3 id="第二轮-技术深挖-60-分钟" tabindex="-1">第二轮：技术深挖（60 分钟） <a class="header-anchor" href="#第二轮-技术深挖-60-分钟" aria-label="Permalink to &quot;第二轮：技术深挖（60 分钟）&quot;">​</a></h3><p>往死里问项目细节，会追问到你答不上来为止。</p><p><strong>重点</strong>：真实性和深度。</p><p><strong>典型追问链</strong>：</p><blockquote><p>&quot;你说用了混合检索&quot; → &quot;权重怎么定的&quot; → &quot;为什么是这个比例&quot; → &quot;调之前是多少&quot; → &quot;你怎么知道调完更好了&quot; → &quot;评测集多少条&quot; → &quot;评测集怎么来的&quot;</p></blockquote><p>这条链能一路问到底的人，一定是真做过。</p><h3 id="第三轮-系统设计-45-60-分钟" tabindex="-1">第三轮：系统设计（45~60 分钟） <a class="header-anchor" href="#第三轮-系统设计-45-60-分钟" aria-label="Permalink to &quot;第三轮：系统设计（45~60 分钟）&quot;">​</a></h3><p>给一个场景，让你设计系统。</p><p><strong>重点</strong>：架构能力、边界意识、取舍。</p><p><strong>典型题目</strong>：设计一个支持 10 万文档、500 并发、多租户隔离的企业知识库。</p><p><strong>准备</strong>：背熟第 10 章的架构图，并且能讲清每个组件的必要性（&quot;为什么需要模型网关&quot;而不是&quot;我们有个网关&quot;）。</p><h3 id="第四轮-编码-45-60-分钟" tabindex="-1">第四轮：编码（45~60 分钟） <a class="header-anchor" href="#第四轮-编码-45-60-分钟" aria-label="Permalink to &quot;第四轮：编码（45~60 分钟）&quot;">​</a></h3><p>写代码。通常不是算法题，是工程题。</p><p><strong>典型题目</strong>：实现一个带重试和流式的模型调用封装；实现一个简单的 RAG 检索函数。</p><p><strong>重点</strong>：代码质量、异常处理、边界情况。</p><h3 id="第五轮-hr-交叉面" tabindex="-1">第五轮：HR / 交叉面 <a class="header-anchor" href="#第五轮-hr-交叉面" aria-label="Permalink to &quot;第五轮：HR / 交叉面&quot;">​</a></h3><p>问动机、稳定性、薪资。</p><p><strong>重点</strong>：你为什么转、能不能扛住不确定性。</p><p><strong>准备</strong>：不要说&quot;AI 是趋势所以我想转&quot;。要说具体的东西：你做了什么、发现了什么问题、想解决什么。</p><h2 id="六、一个残酷的判断" tabindex="-1">六、一个残酷的判断 <a class="header-anchor" href="#六、一个残酷的判断" aria-label="Permalink to &quot;六、一个残酷的判断&quot;">​</a></h2><p>面试能不能过，<strong>七成取决于你有没有一个真做过、有数字、能扛住三层追问的项目</strong>，三成才是知识点覆盖。</p><p>所以如果你的时间有限，优先级应该是：</p><ol><li>做一个能扛住追问的项目（占 60% 时间）</li><li>把项目的每个技术选择都想清楚&quot;为什么&quot;（占 25% 时间）</li><li>补知识点盲区（占 15% 时间）</li></ol><p>反过来做——先刷完所有知识点再动手——你会发现自己能背出 RAG 的定义，但答不上&quot;你的分块大小是多少、为什么&quot;。</p><p><strong>下一步</strong>：读 <a href="/ai-eng-roadmap/guide/15-interview">15 · 面试题库</a> 自测，然后按 <a href="/ai-eng-roadmap/guide/16-projects">16 · 项目实战</a> 动手。</p>',79)])])}const q=o(e,[["render",n]]);export{g as __pageData,q as default};
